export const getRotateSecretUrl = (secretId: string,) => {




  return `/api/v1/secrets/${secretId}/versions`
}

/**
 * The new value becomes the next version; every older value is destroyed. Jobs claimed from now on receive it.
 * @summary Rotate a secret to a new value (secret.rotate)
 */
export const rotateSecret = async (secretId: string,
    secretRotateRequest: SecretRotateRequest, options?: Parameters<typeof customFetch>[1]): Promise<Secret> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<Secret>(getRotateSecretUrl(secretId),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(secretRotateRequest)
  }
);}





export const getRotateSecretQueryKey = (secretId: string,
    secretRotateRequest?: SecretRotateRequest,) => {
    return [
    'POST', `/api/v1/secrets/${secretId}/versions`, secretRotateRequest
    ] as const;
    }


