   return  { queryKey, queryFn, enabled: secretId !== null && secretId !== undefined, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof rotateSecret>>, TError, TData> & { queryKey: DataTag<QueryKey, TData, TError> }
